public class DOMNodePointer_testNode_TriageGen1Test {

    private Node mockNode;

    @Before
    public void setUp() {
        mockNode = mock(Node.class);
    }

    @Test
    public void testNullTest() {
        assertTrue(DOMNodePointer.testNode(mockNode, null));
    }

    @Test
    public void testUnknownTestType() {
        NodeTest unknownTest = mock(NodeTest.class);
        assertFalse(DOMNodePointer.testNode(mockNode, unknownTest));
    }

    @Test
    public void testNodeNameTest_NotElementNode() {
        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        NodeNameTest nameTest = mock(NodeNameTest.class);
        assertFalse(DOMNodePointer.testNode(mockNode, nameTest));
    }

    @Test
    public void testNodeNameTest_WildcardNoPrefix() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(true);
        when(nameTest.getNodeName()).thenReturn(new QName("any"));
        when(nameTest.getNamespaceURI()).thenReturn(null);
        when(nameTest.getNodeName().getPrefix()).thenReturn(null);

        assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
    }

    @Test
    public void testNodeNameTest_SuccessMatchingLocalAndNS() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        QName qname = new QName("http://test", "local");
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(false);
        when(nameTest.getNodeName()).thenReturn(qname);
        when(nameTest.getNamespaceURI()).thenReturn("http://test");

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("local");
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(mockNode)).thenReturn("http://test");
            mockedStatic.when(DOMNodePointer::getPrefix).thenReturn("p"); // dummy for static call if needed

            // Note: equalStrings is likely a private helper in the same class, 
            // assuming it works as standard string equality.
            assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_WildcardTrue() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        QName qname = new QName("p", "local");
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(true);
        when(nameTest.getNodeName()).thenReturn(qname);
        when(nameTest.getNamespaceURI()).thenReturn("http://test");

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(mockNode)).thenReturn("http://test");
            assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_MismatchLocalName() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(false);
        when(nameTest.getNodeName()).thenReturn(new QName("local"));

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("different");
            assertFalse(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_NamespaceMismatch() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(false);
        when(nameTest.getNodeName()).thenReturn(new QName("http://a", "local"));
        when(nameTest.getNamespaceURI()).thenReturn("http://a");

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("local");
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(mockNode)).thenReturn("http://b");
            assertFalse(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeNameTest_PrefixMatchWithNullNS() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        NodeNameTest nameTest = mock(NodeNameTest.class);
        when(nameTest.isWildcard()).thenReturn(false);
        when(nameTest.getNodeName()).thenReturn(new QName("p", "local"));
        when(nameTest.getNamespaceURI()).thenReturn("p");

        try (MockedStatic<DOMNodePointer> mockedStatic = mockStatic(DOMNodePointer.class)) {
            mockedStatic.when(() -> DOMNodePointer.getLocalName(mockNode)).thenReturn("local");
            mockedStatic.when(() -> DOMNodePointer.getNamespaceURI(mockNode)).thenReturn(null);
            mockedStatic.when(() -> DOMNodePointer.getPrefix(mockNode)).thenReturn("p");
            assertTrue(DOMNodePointer.testNode(mockNode, nameTest));
        }
    }

    @Test
    public void testNodeTypeTest() {
        NodeTypeTest typeTest = mock(NodeTypeTest.class);

        // NODE_TYPE_NODE
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.DOCUMENT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // NODE_TYPE_TEXT
        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_TEXT);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.CDATA_SECTION_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // NODE_TYPE_COMMENT
        when(mockNode.getNodeType()).thenReturn(Node.COMMENT_NODE);
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_COMMENT);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // NODE_TYPE_PI
        when(mockNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(typeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_PI);
        assertTrue(DOMNodePointer.testNode(mockNode, typeTest));

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));

        // Unknown Type in switch
        when(typeTest.getNodeType()).thenReturn(999);
        assertFalse(DOMNodePointer.testNode(mockNode, typeTest));
    }

    @Test
    public void testProcessingInstructionTest() {
        ProcessingInstructionTest piTest = mock(ProcessingInstructionTest.class);
        when(piTest.getTarget()).thenReturn("target_val");

        // Case: Not a PI node
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, piTest));

        // Case: Is a PI node, but target mismatch
        when(mockNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        ProcessingInstruction mockPI = mock(ProcessingInstruction.class);
        when(mockPI.getTarget()).thenReturn("other");
        // We need to cast the mock node to ProcessingInstruction for the logic to work
        // In a real scenario, mockNode would be a ProcessingInstruction instance
        Node piNode = mock(ProcessingInstruction.class);
        when(piNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(piNode.getTarget()).thenReturn("other");
        assertFalse(DOMNodePointer.testNode(piNode, piTest));

        // Case: Is a PI node, target matches
        ProcessingInstruction matchingPI = mock(ProcessingInstruction.class);
        when(matchingPI.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(matchingPI.getTarget()).thenReturn("target_val");
        assertTrue(DOMNodePointer.testNode(matchingPI, piTest));
    }
}

// Stub interface to make the code compile if not in classpath
interface ProcessingInstruction extends Node {
    String getTarget();
}
